function l(t,a="YYYY-MM-DD"){const e=typeof t=="string"?new Date(t):t,c=e.getFullYear().toString(),i=(e.getMonth()+1).toString().padStart(2,"0"),o=e.getDate().toString().padStart(2,"0"),n=e.getHours().toString().padStart(2,"0"),r=e.getMinutes().toString().padStart(2,"0"),s=e.getSeconds().toString().padStart(2,"0");return a.replace(/YYYY/g,c).replace(/MM/g,i).replace(/DD/g,o).replace(/HH/g,n).replace(/mm/g,r).replace(/ss/g,s)}function f(t){const a=typeof t=="string"?new Date(t):t,c=new Date().getTime()-a.getTime(),i=Math.floor(c/1e3),o=Math.floor(i/60),n=Math.floor(o/60),r=Math.floor(n/24),s=Math.floor(r/30),g=Math.floor(s/12);return g>0?`${g}年前`:s>0?`${s}个月前`:r>0?`${r}天前`:n>0?`${n}小时前`:o>0?`${o}分钟前`:"刚刚"}export{l as f,f as r};
